function MoldFlaskAlignmentPinMaker.init() MoldFlaskAlignmentPinMaker.ironStock=18; MoldFlaskAlignmentPinMaker.bronzeStock=14; MoldFlaskAlignmentPinMaker.woodStock=10; MoldFlaskAlignmentPinMaker.leatherStock=8; MoldFlaskAlignmentPinMaker.silverStock=8; MoldFlaskAlignmentPinMaker.goldStock=6; MoldFlaskAlignmentPinMaker.jewelStock=4; MoldFlaskAlignmentPinMaker.pearlStock=4; MoldFlaskAlignmentPinMaker.productStock={}; MoldFlaskAlignmentPinMaker.buildings={}; MoldFlaskAlignmentPinMaker.maker=nil; MoldFlaskAlignmentPinMaker.activeMaking={}; MoldFlaskAlignmentPinMaker.totalProducts=0; MoldFlaskAlignmentPinMaker.dayTimer=0; print("[MoldFlaskAlignmentPinMaker] Royal Mold Flask Alignment Pin Maker System initialized (6 products, 4 buildings)") end
function MoldFlaskAlignmentPinMaker.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; MoldFlaskAlignmentPinMaker.maker={name=n or ("Boltnik "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Boltnik najet: %s (spretnost: %d)",MoldFlaskAlignmentPinMaker.maker.name,s),"success") end; return true end
function MoldFlaskAlignmentPinMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function MoldFlaskAlignmentPinMaker.build(id) local ok,e=MoldFlaskAlignmentPinMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(MoldFlaskAlignmentPinMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function MoldFlaskAlignmentPinMaker.getQualityBonus() local b=0; for _,bd in ipairs(MoldFlaskAlignmentPinMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function MoldFlaskAlignmentPinMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and MoldFlaskAlignmentPinMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and MoldFlaskAlignmentPinMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and MoldFlaskAlignmentPinMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and MoldFlaskAlignmentPinMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and MoldFlaskAlignmentPinMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and MoldFlaskAlignmentPinMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and MoldFlaskAlignmentPinMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and MoldFlaskAlignmentPinMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #MoldFlaskAlignmentPinMaker.buildings==0 then return false,"Potrebna boltna delavnica" end; if not MoldFlaskAlignmentPinMaker.maker then return false,"Potreben boltnik" end; return true end
function MoldFlaskAlignmentPinMaker.make(pt,qty) qty=qty or 1; local ok,e=MoldFlaskAlignmentPinMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then MoldFlaskAlignmentPinMaker.ironStock=MoldFlaskAlignmentPinMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then MoldFlaskAlignmentPinMaker.bronzeStock=MoldFlaskAlignmentPinMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then MoldFlaskAlignmentPinMaker.woodStock=MoldFlaskAlignmentPinMaker.woodStock-d.woodCost*qty end; if d.leatherCost then MoldFlaskAlignmentPinMaker.leatherStock=MoldFlaskAlignmentPinMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then MoldFlaskAlignmentPinMaker.silverStock=MoldFlaskAlignmentPinMaker.silverStock-d.silverCost*qty end; if d.goldCost then MoldFlaskAlignmentPinMaker.goldStock=MoldFlaskAlignmentPinMaker.goldStock-d.goldCost*qty end; if d.jewelCost then MoldFlaskAlignmentPinMaker.jewelStock=MoldFlaskAlignmentPinMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then MoldFlaskAlignmentPinMaker.pearlStock=MoldFlaskAlignmentPinMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if MoldFlaskAlignmentPinMaker.maker then t=math.max(1,t-math.floor(MoldFlaskAlignmentPinMaker.maker.skill/13)) end; table.insert(MoldFlaskAlignmentPinMaker.activeMaking,{id="moldflaskalignmentpin_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function MoldFlaskAlignmentPinMaker.completeMaking(m) local q=1.0+(MoldFlaskAlignmentPinMaker.getQualityBonus()/100); if MoldFlaskAlignmentPinMaker.maker then q=q+(MoldFlaskAlignmentPinMaker.maker.skill/140) end; q=math.min(2.5,q); MoldFlaskAlignmentPinMaker.productStock[m.productType]=(MoldFlaskAlignmentPinMaker.productStock[m.productType] or 0)+m.quantity; MoldFlaskAlignmentPinMaker.totalProducts=MoldFlaskAlignmentPinMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if MoldFlaskAlignmentPinMaker.maker then MoldFlaskAlignmentPinMaker.maker.itemsMade=MoldFlaskAlignmentPinMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then MoldFlaskAlignmentPinMaker.maker.skill=math.min(100,MoldFlaskAlignmentPinMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Bolt izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"moldflaskalignmentpin.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function MoldFlaskAlignmentPinMaker.update(dt) if not _G.state then return end; MoldFlaskAlignmentPinMaker.dayTimer=MoldFlaskAlignmentPinMaker.dayTimer+dt; if MoldFlaskAlignmentPinMaker.dayTimer>=30 then MoldFlaskAlignmentPinMaker.dayTimer=0; for i=#MoldFlaskAlignmentPinMaker.activeMaking,1,-1 do local m=MoldFlaskAlignmentPinMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then MoldFlaskAlignmentPinMaker.completeMaking(m); table.remove(MoldFlaskAlignmentPinMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(MoldFlaskAlignmentPinMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if MoldFlaskAlignmentPinMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function MoldFlaskAlignmentPinMaker.getStats() return {ironStock=MoldFlaskAlignmentPinMaker.ironStock,bronzeStock=MoldFlaskAlignmentPinMaker.bronzeStock,woodStock=MoldFlaskAlignmentPinMaker.woodStock,leatherStock=MoldFlaskAlignmentPinMaker.leatherStock,silverStock=MoldFlaskAlignmentPinMaker.silverStock,goldStock=MoldFlaskAlignmentPinMaker.goldStock,jewelStock=MoldFlaskAlignmentPinMaker.jewelStock,pearlStock=MoldFlaskAlignmentPinMaker.pearlStock,productStock=MoldFlaskAlignmentPinMaker.productStock,numBuildings=#MoldFlaskAlignmentPinMaker.buildings,hasMaker=MoldFlaskAlignmentPinMaker.maker~=nil,makerName=MoldFlaskAlignmentPinMaker.maker and MoldFlaskAlignmentPinMaker.maker.name or "—",makerSkill=MoldFlaskAlignmentPinMaker.maker and MoldFlaskAlignmentPinMaker.maker.skill or 0,activeMaking=#MoldFlaskAlignmentPinMaker.activeMaking,totalProducts=MoldFlaskAlignmentPinMaker.totalProducts} end
